    (62, "Maza kakhui, thot-thotli masham katha.", "Separates fine golden rice from chaff with a rhythmic toss.", "हल्के झटकों से भूसे को उड़ाकर साफ चावल अलग कर देता है।", "Yang / Winnowing fan", "Winnowing Tray", "सूप / सूपड़ा"),
    (63, "Awui shimli kapam, ngaya tharan kakhikha ngatan.", "Guards the family's traditional woven shawls inside wooden boxes.", "पारंपरिक शॉल और कीमती वस्त्रों को सहेजकर रखने वाला संदूक।", "Khuishim", "Wooden Chest", "लकड़ी का संदूक"),
    (64, "Kharurungli tara, meili kathi tharan chakhāng.", "Liquid inside the pot, turns into hearty solid staple when boiled.", "पहले पानी में तैरता है, उबलने के बाद पेट भरने वाला ठोस भोजन बन जाता है।", "Chā / Cooked Rice", "Cooked Rice", "पका हुआ भात / चावल"),
    (65, "Phei akha, apang kathum eina kaphung katoh.", "A tripod stool carved from a single log for elders by the fire.", "एक ही लकड़ी से तराशी गई तीन पैरों वाली पारंपरिक चौकी।", "Chakrei", "Wooden Hearth Stool", "लकड़ी का तिपाया स्टूल"),
    (66, "Apang phei makalei, shim saikora kaphungli lei.", "Has no arms, but holds up the huge thatched roof through stormy winds.", "हाथ नहीं हैं, पर आँधी-तूफान में पूरे छप्पर को संभाले रखता है।", "Yumshang / Pillar", "Central House Pillar", "घर का मुख्य खंभा"),
    (67, "Meira khangatar, awui kachonli kaza saikora phung.", "Holds warm drinking water inside a dried hollow gourd.", "सूखी हुई गोल लौकी, जिसमें ठंडा और मीठा पानी भरकर खेत ले जाते हैं।", "Theikhur", "Dried Gourd Canteen", "तूंबा / सूखी लौकी की बोतल"),
    (68, "Khari makalei, kaphung eina kashao saikora kakon.", "Cleans muddy footsteps from the porch with stiff bristles.", "सख्त झाड़ू जो बरामदे से कीचड़ और धूल साफ़ कर देती है।", "Shimphei-kharek", "Straw Broom", "झाड़ू"),
    (69, "Awui amik kathuk, kha kakhikha ngatingli kathei.", "Penetrates thick night shadows with a beam of glowing oil.", "तेल की बाती से रात के अंधेरे को चीरता हुआ प्रकाश देता है।", "Meira / Oil Lamp", "Clay Oil Lamp", "मिट्टी का दीया"),
    (70, "Akhon phungda rā, shim khavai saikora kakon.", "Rings clearly to announce morning service across the misty valley.", "पहाड़ी घाटी में सुबह की प्रार्थना और सभा का संदेश देती है।", "Ganta / Bell", "Church Bell", "घंटी / घंटा"),

    # Section 3: Living Beings & Human Anatomy (71–100)
    (71, "Akui akha eina thot-thotli mik-khano kathum lei.", "One single head bearing three unblinking eyes.", "एक ही सिर है, पर उस पर तीन आँखें बनी होती हैं।", "Chaphung / Coconut", "Coconut", "नारियल"),
    (72, "Shim akha wui chitharan kachir khani phāfa.", "Two windows of one house that open and shut together.", "एक ही घर की दो खिड़कियाँ, जो साथ खुलती और बंद होती हैं।", "Amik", "Eyes", "दोनों आँखें"),
    (73, "Mayarnaobing kacham saikora, kha kachir akha eina ngasot pamei.", "Thirty-two white warriors standing guard inside a red enclosure.", "बत्तीस सफे द सिपाही जो हमेशा एक लाल घेरे के भीतर पहरा देते हैं।", "Aha eina Malei", "Teeth and Tongue", "दाँत और जीभ"),
    (74, "Na zatli azat, na pamli apam, kha na khanukhungli mathei.", "Walks when you walk, rests when you sit, disappears in shadows.", "तुम चलो तो साथ चले, बैठो तो बैठ जाए, अंधेरे में गायब हो जाए।", "Mahor", "Shadow", "परछाई"),
    (75, "Kacham shanao akha, awui shimli kakharak machuk.", "A princess asleep inside a house with neither doors nor windows.", "एक ऐसी राजकुमारी जो बिना खिड़की-दरवाजे वाले सफ़े द घर में सोती है।", "Har-e / Har-anao", "Egg", "अंडा"),
    (76, "Apang phungda zat, kha phei makalei; shim phungda kazat.", "Has no feet, yet moves across wet stones carrying its house on its back.", "बिना पैरों के चलता है और अपना पूरा घर पीठ पर लादकर घूमता है।", "Khomok", "Snail", "घोंघा"),
    (77, "Ngashunli kashan kazat, ngaya tharan akui chili kapam.", "Wears a scarlet crown by day, wakes the whole ridge at dawn.", "सिर पर लाल कलंगी पहनकर चलता है और सुबह होते ही सबको जगाता है।", "Har mayara", "Rooster", "मुर्गा"),
    (78, "Na khikha kaza makhano, kha ngashun-ngaya kuiphungli lei.", "Takes no food from you, yet grows like a dense forest upon your crown.", "जिसे कभी खाना नहीं देना पड़ता, फिर भी सिर पर जंगल की तरह बढ़ता है।", "Kuisam", "Hair", "सिर के बाल"),
    (79, "Kakhon akha eina kathem, awui shimli phei mati.", "Carries four legs, sleeps under the kitchen hearth, snorts in mud.", "चार पैरों वाला, चूल्हे के नीचे सोता है और कीचड़ में मस्त रहता है।", "Hok", "Pig", "सूअर"),
    (80, "Apang phei makalei, kha thingrong saikora kaphung katoh.", "Has neither arms nor legs, but slithers up tall forest trees.", "बिना हाथ-पैर के भी ऊँ चे पेड़ों पर रेंगता हुआ चढ़ जाता है।", "Pha / Snake", "Snake", "साँप"),
    (81, "Phei taruk eina kachathat, meira katha ngaphar.", "Has six tiny legs and carries a sparkling lamp in its tail at night.", "छह नन्हें पैरों वाला, रात में पूंछ में चमकता दीया लिए उड़ता है।", "Meiphung-khamara", "Firefly", "जुगनू"),
    (82, "Shim akha wui kachir khani, tara kashan phāfa.", "Two soft caves on a hill that breathe air day and night.", "पहाड़ी पर बनी दो गुफाएँ, जो रात-दिन हवा अंदर-बाहर करती हैं।", "Natang", "Nostrils / Nose", "नाक के नथुने"),
    (83, "Kachon akha paimi, kacham tharan ngachon pamei.", "Flutters like a flower petal on warm autumn mornings.", "खेतों और फूलों पर रंग-बिरंगी पंखुड़ियों की तरह उड़ती है।", "Khamara / Butterfly", "Butterfly", "तितली"),
    (84, "Kakhikha kaza makano, kha ngashun-ngaya akhon phung kazat.", "Never drinks or eats, but keeps beating rhythmically inside your chest.", "न कुछ खाता है न पीता है, पर सीने में धक-धक करता रहता है।", "Thang / Heart", "Heart", "हृदय / दिल"),
    (85, "Kachir akha eina kashung, kacham tharan tara rā-mi.", "A red pool between lips that can speak sweet words or bitter arrows.", "होंठों के बीच एक ऐसी जगह जहाँ से मीठे बोल या कड़वे बाण निकलते हैं।", "Malei / Khamor", "Tongue / Mouth", "जीभ / वाणी"),
    (86, "Ngashunli khangapa, ngaya tharan amik kachang.", "Hunts silently in the dark forest with large glowing yellow eyes.", "रात के सन्नाटे में बड़ी-बड़ी पीली आँखों से शिकार तलाशता है।", "Khuinao / Owl", "Owl", "उल्लू"),
    (87, "Kakhon akha eina ring, phei mati eina phungkazat.", "Four sturdy pillars beneath, a swishing tail behind, grazing on the green hills.", "नीचे चार खंभे, पीछे एक पूंछ, और पहाड़ी ढलानों पर चरती है।", "Simuk", "Cow", "गाय"),
    (88, "Amik akha leisangda, awui shimli kaphung katoh.", "Spins a sticky silk palace in dark corners without hands.", "बिना हाथों के कोने-कोने में रेशमी महल बुनती है।", "Chikhamak / Spider", "Spider", "मकड़ी"),
    (89, "Aphei akha eina kazat, kaphungli kashao saikora phung.", "Hops on high branches, chirps brightly to greet the sunrise.", "ऊँ ची टहनियों पर फुदकती है और चहचहाकर सुबह का स्वागत करती है।", "Vanao", "Bird", "चिड़िया / पक्षी"),
    (90, "Kachir khani phāfa, kakhon saikora kashang.", "Two wide soft dishes on either side of the head that capture every whisper.", "सिर के दोनों तरफ़ लगे दो पंखे, जो हर फुसफुसाहट को सुन लेते हैं।", "Akhana", "Ears", "दोनों कान"),
    (91, "Awui shimli kaza phung, awui khari kachang.", "Produces golden sweet syrup from wild blossoms inside hollow trees.", "जंगली फूलों से मीठा रस चुराकर पेड़ के खोखल में भर देती है।", "Khangra / Honeybee", "Honeybee", "मधुमक्खी"),
    (92, "Phei mati leisangda, shimli kashuk khalen saikora huimi.", "Barks fiercely at strangers, wags its tail affectionately for master.", "अजनबियों को देखकर भौंकता है, मालिक के आते ही दुम हिलाता है।", "Fa", "Dog", "कुत्ता"),
    (93, "Tara zangli kapam, phei makalei chathat kazat.", "Swims like a dart through mountain streams without needing lungs.", "बिना फेफड़ों के बर्फीले पहाड़ी पानी में तीर की तरह तैरती है।", "Khai", "Fish", "मछली"),
    (94, "Apang phei akha eina thot-thotli masham katha.", "Five small brothers of unequal height who live together on one palm.", "पाँच छोटे-बड़े भाई, जो एक ही हथेली पर हमेशा साथ रहते हैं।", "Apang-kanao", "Fingers", "हाथ की उँगलियाँ"),
    (95, "Akui makalei, phei mati eina phung kazat.", "Creeps quietly through the tall grass, hunts mice near grain baskets.", "दबे पाँव चलती है और अनाज की टोकरी के पास चूहे का शिकार करती है।", "Lami", "Cat", "बिल्ली"),
    (96, "Kaphung tharan kazat, awui ngachonli tarā phung kazat.", "Digs deep tunnels underground with sharp front claws in the dark.", "अपने पैने पंजों से ज़मीन के नीचे गहरी सुरंगें खोद लेता है।", "Shiwok", "Mole / Rat", "चूहा / छछूंदर"),
    (97, "Ngashunli tara mathik, ngaya tharan chimik kakha.", "Sits on riverside rocks, leaps with long green legs into the pool.", "नदी किनारे पत्थरों पर बैठता है और लंबे हरे पैरों से पानी में कूदता है।", "Kharok / Frog", "Frog", "मेंढक"),
    (98, "Kachon akha paimi, kacham tharan ngachon pamei.", "Walks softly on cushions, carries sharp curved claws tucked in its paws.", "मखमली गद्दों पर चलता है, पर पंजों में तेज़ नुकीले नाखून छिपाए रखता है।", "Lami-kanao / Tiger-cat", "Leopard cat / Wild cat", "जंगली बिल्ली / चीता"),
    (99, "Phei mati eina kazat, awui kuiphungli ngalang phung.", "Carries two curved horns on its head, climbs jagged cliffs with sure hooves.", "सिर पर दो मुड़े हुए सींग लिए पथरीली चट्टानों पर आसानी से चढ़ जाती है।", "Meishao / Mountain goat", "Wild Mountain Goat / Serow", "जंगली पहाड़ी बकरी"),
    (100, "Mayarnaobing saikora, awui phei khani eina okathui zat.", "Walks erect on two feet, gifted with speech and wisdom over all beasts.", "दो पैरों पर सीधा चलता है, जिसे बोलने और सोचने की शक्ति मिली है।", "Minao / Man", "Human Being / Man", "मनुष्य / इंसान"),

    # Section 4: Forest Flora, Fauna & Mountain Life (101–125)
    (101, "Kaphung kharām ngachonli chathat, amik thei marang.", "Hears the rustle in the dark forest canopy, strikes with silent wings.", "जंगल की ऊँ चाई पर आहट सुनता है और बिना आवाज़ किए झपट्टा मारता है।", "Khuinao", "Eagle / Hawk", "बाज / चील"),
    (102, "Kachon akha paimi, kachāng saikora ngava.", "Blooms only once a year on the misty crest of Kashong peak.", "साल में केवल एक बार शिरुई पर्वत की चोटी पर खिलता है।", "Shirui Kashong Won (Shirui Lily)", "Shirui Lily", "शिरुई लिली (दुर्लभ फूल)"),
    (103, "Thingrongli kapam, awui kachonli kuisam ngaphar.", "Parasite resting high in oak branches, green even when leaves fall.", "बांज के पेड़ों पर रहने वाली हरी अमरबेल, जो कभी नहीं सूखती।", "Thing-won / Orchid", "Wild Tree Orchid", "जंगली ऑर्किड"),
    (104, "Phei mati leisangda, awui amik meira katha ching.", "Creeps along forest trails by night, eyes glowing like burning coal.", "रात में जंगल की पगडंडी पर चलता है, आँखें अंगारे जैसी चमकती हैं।", "Haora / Wild Dog", "Asiatic Wild Dog / Dhole", "जंगली कुत्ता / ढोल"),
    (105, "Tara kashanli rurung, apang akha eina kathem saikora kakon.", "Long bill dipping into pebble brooks to snatch darting minnows.", "लंबी चोंच से पहाड़ी पत्थरों के बीच से मछलियाँ पकड़ता है।", "Tara-vanao", "Kingfisher", "नीलकंठ / किलकिला"),
    (106, "Awui shimli kapam, awui phei taruk eina kaphung katoh.", "Tiny army carrying loads ten times their weight along bamboo fences.", "नन्हीं सेना जो अपने वज़न से दस गुना भारी दाना ढोकर ले जाती है।", "Makhang-anao", "Ants", "चींटियाँ"),
    (107, "Kazingrot kachi tharan akhon phungda rā, saikora ngazek.", "Croaks loudly from wet terrace ditches when the monsoon rains break.", "मानसून आते ही सीढ़ीदार खेतों के गड्ढों से टर्र-टर्र शोर मचाता है।", "Kharok-kakhon", "Croaking bullfrog", "मेंढक की टर्र-टर्र"),
    (108, "Awui kuiphungli kashao, thingrongli kaphung katoh.", "Hammers hollow dry trees like an axe to find beetles.", "कुल्हाड़ी की तरह पेड़ के तने को ठक-ठक ठोककर कीड़े निकालता है।", "Thing-kakhon vanao", "Woodpecker", "कठफोड़वा"),
    (109, "Kuisam makalei, awui aphei eina tingri kashan.", "Builds deep underwater burrows beneath mossy riverside stones.", "नदी के पत्थरों के नीचे बिल बनाकर रहने वाला जल-जीव।", "Tara-wok / Crab", "Freshwater Mountain Crab", "पहाड़ी केकड़ा"),
    (110, "Kachon kathir, awui kachir eina tara mathik.", "Spins fine silk cocoons among wild castor leaves in autumn.", "जंगली अरंडी के पत्तों पर रेशमी कोकून बनाने वाला कीड़ा।", "Lengshik", "Silkworm / Eri worm", "रेशम कीट"),
    (111, "Ngashunli khangapa, ngaya tharan meira phung kazat.", "Hunts flying moths in darkness using silent sound waves.", "रात के सन्नाटे में पंखों की फड़फड़ाहट से कीड़े पकड़ती है।", "Ngashik / Bat", "Bat", "चमगादड़"),
    (112, "Thingrong saikora chathat, awui amik kathuk.", "Drills holes deep into timber without hammer or chisel.", "बिना छेनी-हथौड़े के मजबूत लकड़ी में छेद कर देता है।", "Thing-chikhur kaza", "Wood borer beetle", "घुन / लकड़ी का कीड़ा"),
    (113, "Aphei akha leisangda, tingri tharan kaphung katoh.", "Spreads a soft umbrella on rotting forest logs after heavy rain.", "सड़ी लकड़ी पर बारिश के बाद नन्हीं छतरी की तरह उग आता है।", "U-chik / Mushroom", "Wild Forest Mushroom", "जंगली खुंबी / कुकुरमुत्ता"),
    (114, "Awui kachonli kuisam phung, chitharan ngakhum.", "Bristles with a thousand sharp quills to repel leopards.", "अपने शरीर पर हज़ारों नुकीले कांटे लिए घूमता है।", "Phangwon / Porcupine", "Porcupine", "साही (कंटीला जीव)"),
    (115, "Meira khangatar, awui ngachonli saikora kazip.", "Fills the autumn air with deafening song from high pine branches.", "चीड़ के पेड़ों पर बैठकर पूरी घाटी में झींगुर जैसा शोर मचाती है।", "Zinglik / Cicada", "Cicada", "झींगुर / सिकाडा"),
    (116, "Kaphung ngashanli kathem, kachon kashan phung.", "Thick aromatic pine resin used to light old mountain hearths.", "चीड़ की खुशबूदार लकड़ी जो आग जलाने में तुरंत भड़क उठती है।", "Thing-ngasui / Pine resin", "Pine resin / Pitch wood", "चीड़ का छिल्का / लीसा"),
    (117, "Tara mathik, kaphung wui eina shimli rā-pam.", "Mountain moss that stays green and spongy through frozen winter.", "सर्दियों में भी हरी-भरी रहने वाली नम पहाड़ी काई।", "Tingri-khomok", "Moss", "काई / मॉस"),
    (118, "Awui kachir eina tara rā-mi, thingrongli kaphung katoh.", "Giant bamboo reed that carries mountain water down to the village square.", "बाँस की लंबी नाली जिससे पहाड़ का ठंडा पानी गाँव तक लाया जाता है।", "Pui-khalang", "Bamboo Aqueduct / Pipe", "बाँस का पानी का पाइप"),
    (119, "Ngashunli chitharan kazat, ngaya tharan shimli pam.", "Forest fowl that roosts high up in branches to escape foxes.", "जंगली तीतर जो लोमड़ी से बचने के लिए ऊँ ची डाल पर सोता है।", "Vanao-ngakhon / Partridge", "Wild Partridge", "तीतर / जंगली मुर्गी"),
    (120, "Kachon akha paimi, kacham tharan ngachon pamei.", "Wild ginger root hiding underground, warming winter soups.", "ज़मीन के नीचे छिपा तीखा कंद जो सर्दियों के सूप को तीखा करता है।", "Thing-khur / Wild Ginger", "Wild Ginger", "जंगली अदरक"),
    (121, "Phei mati leisangda, kaphungli kashao saikora kakon.", "Stout mountain pony trotting surefootedly on narrow cliff ridges.", "संकरे पहाड़ी रास्तों पर बिना फिसले भारी बोझ ढोने वाला टट्टू।", "Sigui-kanao", "Mountain Pony", "पहाड़ी घोड़ा / टट्टू"),
