    (177, "Ngashunli kashan kazat, ngaya tharan akui chili kapam.", "Carved wooden water ladle dipped into large drinking jars.", "पानी के मटके से पानी निकालने वाला लकड़ी का लंबा करछुल।", "Thing-khamak", "Wooden Water Ladle", "लकड़ी का करछुल"),
    (178, "Na khikha kaza makhano, kha kuiphungli lei.", "Coarse straw mat spread on earth for elders to sit by the fire.", "आग के पास बैठकर धूप सेकने के लिए बिछाई जाने वाली पुआल की चटाई।", "Chā-pui", "Straw Sitting Mat", "पुआल की चटाई"),
    (179, "Kakhon akha eina kathem, awui shimli phei mati.", "Small wooden coop perched on stilts to keep hens safe from snakes.", "मुर्गियों को सांप और नेवले से बचाने के लिए ऊँ चा बना दड़बा।", "Har-shim", "Stilt Chicken Coop", "मुर्गी का दड़बा"),
    (180, "Apang phei makalei, kha thingrong saikora kaphung.", "Hollowed-out log boat used to ferry wood across wide mountain rivers.", "एक ही बड़े तने को खोदकर बनाई गई लकड़ी की डोंगी।", "Thing-li", "Dugout Log Canoe", "लकड़ी की डोंगी / नाव"),

    # Section 7: Philosophy, Memory & Kinship (181–200)
    (181, "Phei taruk eina kachathat, meira katha ngaphar.", "Two steady knees that carry a man uphill all his youthful days.", "दो मजबूत घुटने जो जवानी भर इंसान को चढ़ाई पर ले जाते हैं।", "Makhuk", "Knees", "घुटने"),
    (182, "Shim akha wui kachir khani, tara kashan phāfa.", "Broad forehead where elders bear the wrinkles of years and seasons.", "बुजुर्गों का चौड़ा माथा जिस पर जीवन के अनुभवों की लकीरें होती हैं।", "Akui-shon", "Forehead / Brow", "माथा / ललाट"),
    (183, "Kachon akha paimi, kacham tharan ngachon pamei.", "Sharp mind that solves ancient riddles around the dormitory fire.", "तीक्ष्ण बुद्धि जो आग के पास बैठकर पुरानी पहेलियों को सुलझा लेती है।", "Phaning-kashan", "Mind / Intellect", "बुद्धि / विचार"),
    (184, "Kakhikha kaza makano, kha ngashun-ngaya akhon phung.", "The quiet voice of conscience that speaks softly when truth is spoken.", "अंतरात्मा की आवाज़ जो सच बोलने पर हृदय में शांति देती है।", "Ning-kaching", "Conscience / Spirit", "अंतरात्मा / ज़मीर"),
    (185, "Kachir akha eina kashung, kacham tharan tara rā-mi.", "Tears that fall silently when loved ones depart along distant trails.", "अपनों के दूर जाने पर आँखों से चुपचाप बहने वाले आँसू।", "Amik-tara", "Tears", "आँसू"),
    (186, "Ngashunli khangapa, ngaya tharan amik kachang.", "Night dreams that wander across valleys while the body lies still in bed.", "शरीर खाट पर सोता रहता है और मन दूर पहाड़ों में घूमता है।", "Mang", "Dreams in sleep", "सपने / स्वप्न"),
    (187, "Kakhon akha eina ring, phei mati eina phungkazat.", "Gentle breath that enters warm and leaves cool, keeping spirit alive.", "साँस जो अंदर गरम जाती है और जीवन की डोर को थामे रखती है।", "Masi-ring", "Breath of Life", "साँस / प्राणवायु"),
    (188, "Amik akha leisangda, awui shimli kaphung katoh.", "Grey hair that settles like gentle mountain mist upon elder's temples.", "बुढ़ापे में कनपटियों पर उतरने वाली सफ़े द बालों की धुंध।", "Kuisam-ngava", "Grey Hair of Age", "पके हुए सफ़े द बाल"),
    (189, "Aphei akha eina kazat, kaphungli kashao saikora.", "The ten toes that grip the slippery terrace mud during monsoon rains.", "पैरों की दसों उँगलियाँ जो बारिश में सीढ़ीदार खेत की कीचड़ को पकड़ती हैं।", "Aphei-kanao", "Toes", "पैर की उँगलियाँ"),
    (190, "Kachir khani phāfa, kakhon saikora kashang.", "A kind word that heals wounded feelings faster than herbal balm.", "मीठा बोला गया एक शब्द जो जड़ी-बूटी से भी जल्दी घाव भर देता है।", "Kaphā-tui", "Kind Word", "मीठी वाणी"),
    (191, "Awui shimli kaza phung, awui khari kachang.", "An unbending promise made between two lifelong blood brothers.", "दो पक्के दोस्तों के बीच खाई गई अटूट कसम।", "Khamang-tui", "Solemn Oath / Promise", "वचन / प्रतिज्ञा"),
    (192, "Phei mati leisangda, shimli kashuk khalen saikora.", "Old age when a man needs a carved staff to lean upon the slopes.", "वह अवस्था जब पहाड़ पर चलने के लिए लकड़ी की लाठी का सहारा चाहिए।", "Thei-chang / Cane staff", "Walking Stick of Elder", "बुजुर्ग की लाठी"),
    (193, "Tara zangli kapam, phei makalei chathat kazat.", "Village memory preserved without ink in ancient tribal folk songs.", "बिना स्याही के लोक-गीतों में जीवित रहने वाला पुराना इतिहास।", "Khararchān", "Folk Legends / Oral History", "मौखिक इतिहास / लोक-गाथा"),
    (194, "Apang phei akha eina thot-thotli masham katha.", "Two strong shoulders that carry children when rivers run high.", "पिता के मजबूत कंधे जिन पर बैठकर बच्चा नदी पार करता है।", "Apang-shon", "Father's Shoulders", "कंधे"),
    (195, "Akui makalei, phei mati eina phung kazat.", "Generous hospitality that never sends a weary hunter hungry away.", "गाँव का वह सत्कार जो किसी भूखे परदेसी को बिना खिलाए नहीं भेजता।", "Khamiyang", "Hospitality", "आतिथ्य / मेहमाननवाज़ी"),
    (196, "Kaphung tharan kazat, awui ngachonli tarā phung.", "The red rooster's final call signalling that shadows must flee.", "मुर्गे की तीसरी बाँग जो ऐलान करती है कि अंधेरे को जाना होगा।", "Har-kakhon", "Dawn's Cockcrow", "भोर की पहली बाँग"),
    (197, "Ngashunli tara mathik, ngaya tharan chimik kakha.", "Morning mountain mist lifting slowly from the river valley at sunrise.", "सूरज की किरणें पड़ते ही नदी की घाटी से धीरे-धीरे उठने वाला कोहरा।", "Masi-meikhu", "River Valley Mist", "घाटी का कोहरा"),
    (198, "Kachon akha paimi, kacham tharan ngachon pamei.", "The warm embrace of family gathered around the hearth in winter.", "कड़ाके की ठंड में चूल्हे के चारों ओर बैठे परिवार का अपनापन।", "Shimkhur-kakhang", "Family Warmth by Hearth", "पारिवारिक अपनत्व"),
    (199, "Phei mati eina kazat, awui kuiphungli ngalang phung.", "The deep silence of the high Ukhrul pine forests after snowfall.", "बर्फ़बारी के बाद उखरुल के चीड़ के जंगलों में छा जाने वाली गहरी शांति।", "Ngachon-kaphung", "Snowbound Silence of Woods", "जंगल की नीरवता"),
    (200, "Mayarnaobing saikora, awui phei khani eina okathui zat.", "The ancient Tangkhul language handed down through centuries of song and story.", "हज़ारों सालों से गीतों और कहानियों में बहती चली आ रही तंगखुल भाषा।", "Tangkhul Tui", "Tangkhul Language / Heritage", "तंगखुल भाषा और संस्कृति"),

    # Section 8: Hunting, Birds & Mountain Ecology (201–225)
    (201, "Apang phei makalei, tingri saikora kaphung zā.", "Slithers silently through dead bamboo leaves, strikes with hidden fangs.", "बाँस के सूखे पत्तों में बिना आवाज़ रेंगता है और छिपे ज़हर से वार करता है।", "Pha-kakhang (Pit viper)", "Green Pit Viper", "हरी जंगली वाइपर (साँप)"),
    (202, "Kaphung tharan kazat, awui akhon kaphung saikora shao.", "Its hollow barking call echoes off crags before a leopard strikes.", "तेंदुए की आहट पाते ही पहाड़ पर भौंकने जैसी आवाज़ निकालने वाला हिरण।", "Khara-ngashat / Barking deer", "Barking Deer / Muntjac", "काकड़ / भौंकने वाला हिरण"),
    (203, "Awui shimli kapam, awui kachir eina tara mathik.", "Nests inside sheer vertical rock holes where no predator climbs.", "ऊँ ची पथरीली चट्टानों के छेद में घोंसला बनाकर रहने वाला पक्षी।", "Vanao-khur", "Cliff Swallow / Swift", "अबाबील / पहाड़ी पक्षी"),
    (204, "Kachon akha paimi, kacham tharan ngachon pamei.", "Spotted forest predator pacing silently along mossy river ledges.", "नदी के किनारे मखमली पंजों से शिकार तलाशने वाला चित्तीदार शिकारी।", "Khare-ngalang", "Clouded Leopard", "बादलदार तेंदुआ"),
    (205, "Phei mati leisangda, awui amik kathuk.", "Blunt-nosed creature digging out mountain earthworms in damp loam.", "गीली मिट्टी खोदकर पहाड़ी कें चुए खाने वाला चोंचदार जीव।", "Shiwok-ngava", "Shrew / Pangolin", "छछूंदर / पेंगोलिन"),
    (206, "Awui kuiphungli meira lei, chitharan kachang phāfa.", "Huge hornbill flashing black and yellow wings across valley mists.", "धुंध भरी घाटी में काले और पीले पंखों से उड़ने वाला विशाल धनेश।", "Vanaorui / Hornbill", "Great Indian Hornbill", "धनेश पक्षी (हॉर्नबिल)"),
    (207, "Kuisam kathir, kacham tharan ngachon pamei.", "Poison tipped wooden dart shot through a hollow mountain blowpipe.", "बाँस की फूँ कनी से छोड़ा जाने वाला विषैला लकड़ी का बाण।", "Thei-khari", "Blowpipe Dart", "फूँ कनी का तीर"),
    (208, "Ngashunli khangapa, ngaya tharan meira phung kazat.", "Prowls village borders at twilight to steal unwary ducklings.", "शाम ढलते ही गाँव की बाड़ के पास बत्तखों को चुराने वाली लोमड़ी।", "Haora-kanao", "Wild Fox / Jackal", "लोमड़ी / सियार"),
    (209, "Tara kashanli rurung, apang akha eina kathem saikora.", "Swims upside down in river pools catching surface insects.", "नदी के भँवर में उल्टी तैरकर कीड़े पकड़ने वाली छोटी मछली।", "Khai-kanao", "Surface Minnow", "छोटी पहाड़ी मछली"),
    (210, "Thingrong saikora chathat, awui amik kathuk.", "Hard-shelled beetle clinging to tree bark with iron claws.", "पेड़ की छाल को लोहे जैसी पकड़ से जकड़े रहने वाला काला भौंरा।", "Thing-khangra", "Rhinoceros Beetle", "लकड़ी का भौंरा"),
    (211, "Aphei akha leisangda, tingri tharan kaphung katoh.", "Red forest mushroom that bleeds milky sap when cut.", "तोड़ने पर दूधिया रस बहाने वाला लाल जंगली मशरूम।", "U-chik kahung", "Milk-cap Forest Fungus", "दूधिया मशरूम"),
    (212, "Awui kachonli kuisam phung, chitharan ngakhum.", "Tree squirrel leaping between high chestnut branches with a bushy tail.", "घने बालों वाली पूंछ के सहारे शाहबलूत के पेड़ों पर छलाँग लगाने वाली गिलहरी।", "Phang-kanao", "Himalayan Giant Squirrel", "पहाड़ी विशाल गिलहरी"),
    (213, "Meira khangatar, awui ngachonli saikora kazip.", "Chorus of river frogs singing together before the dawn light breaks.", "भोर होने से ठीक पहले नदी के किनारे एक साथ गाने वाले मेंढक।", "Kharok-ngalei", "Riverbed Chorus Frogs", "नदी के मेंढक"),
    (214, "Kaphung ngashanli kathem, kachon kashan phung.", "Wild mountain boar tearing up forest bamboo roots with sharp tusks.", "नुकीले दाँतों से बाँस की जड़ें खोदकर खाने वाला जंगली सूअर।", "Hok-kharam", "Wild Boar", "जंगली सूअर"),
    (215, "Tara mathik, kaphung wui eina shimli rā-pam.", "Water spider gliding effortlessly over stagnant mountain pools.", "रुके हुए पहाड़ी पानी की सतह पर बिना डूबे फिसलने वाला कीड़ा।", "Tara-chikhamak", "Water Strider", "जल-मकड़ी"),
    (216, "Awui kachir eina tara rā-mi, thingrongli kaphung.", "Sap dripping from sliced rubber and wild fig vines in springtime.", "वसंत में जंगली अंजीर और रबड़ की बेल से टपकने वाला गाढ़ा दूध।", "Thing-tara", "Tree Sap / Fig Latex", "पेड़ का दूध / गोंद"),
    (217, "Ngashunli chitharan kazat, ngaya tharan shimli pam.", "Forest pheasant boasting iridescent tail feathers in morning mist.", "सुबह की धुंध में चमकती सतरंगी पूंछ लहराने वाला जंगली तीतर।", "Vanao-ngashing", "Blyth's Tragopan / Pheasant", "मोनाल / जंगली तीतर"),
    (218, "Kachon akha paimi, kacham tharan ngachon pamei.", "Spiny mountain chestnut hull opening in autumn to drop sweet nuts.", "शरद ऋतु में फटकर मीठे फल गिराने वाला काँटेदार शाहबलूत का छिलका।", "Theikashai-khur", "Chestnut Bur", "शाहबलूत का काँटेदार फल"),
    (219, "Phei mati leisangda, kaphungli kashao saikora kakon.", "Black bear climbing tall wild pear trees to shake down ripe fruit.", "पके फल गिराने के लिए नाशपाती के पेड़ पर चढ़ने वाला पहाड़ी भालू।", "Sipam / Mountain bear", "Asiatic Black Bear", "हिमालयी काला भालू"),
    (220, "Awui kachirli tara rā-mi, thingrong kaphung saikora.", "Tree sap turning hard into amber resin on trunk wounds.", "पेड़ के तने पर जम जाने वाला सुनहरा पारदर्शी गोंद।", "Thing-won ngasui", "Tree Gum / Amber", "पेड़ का गोंद / राल"),
    (221, "Kachon kathir, awui kachirli kaza phung.", "Stinging nettle leaf that burns the hand when brushed on ridges.", "पहाड़ी पगडंडी पर छू ते ही हाथ में जलन पैदा करने वाला बिच्छू घास।", "Kashung-pui / Nettle", "Stinging Hill Nettle", "बिच्छू घास / कंडाली"),
    (222, "Apang phei makalei, tingri saikora kaphung katoh.", "Heavy rattan vine used for climbing towering virgin timber.", "ऊँ चे पेड़ों पर चढ़ने के लिए काम आने वाली मजबूत जंगली बेंत की लता।", "Pui-khang", "Climbing Rattan Cane", "मजबूत जंगली बेंत"),
    (223, "Awui kuiphungli meira lei, chitharan kachang phāfa.", "Dragonfly hovering motionless over mountain streams on gossamer wings.", "पहाड़ी झरने के ऊपर हवा में एक जगह थमी रहने वाली पारदर्शी व्याध पतंग।", "Khamara-tara", "Dragonfly", "व्याध पतंग / पतंगा"),
    (224, "Phei taruk eina kachathat, meira katha ngaphar.", "Wasp building intricate mud nests under old eaves without mortar.", "छप्पर के नीचे बिना गारे के मिट्टी का नन्हा घरौंदा बनाने वाली ततैया।", "Khangra-ham", "Mud Dauber Wasp", "कुम्हारी ततैया"),
    (225, "Kachon akha paimi, thot-thotli masham katha.", "Dense mountain mist enveloping Ukhrul peaks like an ocean of milk.", "उखरुल की चोटियों को दूधिया सागर की तरह घेर लेने वाला घना कोहरा।", "Masi-kachang", "Valley Cloud Sea", "पहाड़ी बादलों की चादर"),

    # Section 9: Crafts, Blacksmithing & Utensils (226–250)
    (226, "Apang akha leisangda, awui shimli samphung phung.", "Small bamboo basket worn at the waist to carry snails and crabs.", "नदी में केकड़े और घोंघे पकड़कर कमर पर बाँधने वाली छोटी टोकरी।", "Kharai-kanao", "Waist Gathering Basket", "कमर की टोकरी"),
    (227, "Makhano makaphā, akhon phungda rurung kasa.", "Split bamboo winnowing fan flicking chaff away with rhythmic clicks.", "हाथ के झटके से भूसा उड़ाकर अलग करने वाला हल्का बाँस का सूप।", "Yang-kharei", "Paddy Winnow", "धान का सूप"),
    (228, "Makhana akha eina kathem saikora khavai.", "Carved wooden tobacco pipe shared among village elders at dusk.", "शाम के समय बुजुर्गों द्वारा बारी-बारी से पिया जाने वाला लकड़ी का पाइप।", "Kuiri / Pipe", "Wooden Tobacco Pipe", "लकड़ी का पाइप / हुक्का"),
    (229, "Ngashunli kashuk khalen, ngaya tharan akha eina.", "Pair of bamboo stilts used by young boys during festival games.", "त्योहारों में लड़कों द्वारा बाँस पर चढ़कर दौड़ लगाने वाले खंभे।", "Phei-thing", "Bamboo Stilts", "बाँस की गेड़ी / खंभे"),
    (230, "Amai kathi kharur, meili thikha ngatak.", "Iron chisel used by artisans to carve buffalo emblems on house pillars.", "घर के खंभों पर भैंस और सूर्य के चित्र उके रने वाली लोहे की छेनी।", "Thing-khur ngaphei", "Carving Chisel", "नक्काशी की छेनी"),
    (231, "Apang makalei, chikhikha chithei kashao.", "Split cane broom used to sweep dry chaff from the threshing mat.", "खलिहान की चटाई से भूसा झाड़ने वाली पतली सींकों की झाड़ू।", "Maza-kharek", "Chaff Broom", "सींक की झाड़ू"),
    (232, "Kharurungli phei kathum, meili phei mangapa.", "Clay griddle used for roasting corn ears over white embers.", "अंगारों पर भुट्टे और शकरकंद भूनने वाला मिट्टी का छिद्रित तवा।", "Ham-phei", "Clay Roasting Griddle", "मिट्टी का भूनने वाला तवा"),
    (233, "Kazing eina tarā khayang, kapam tharan kuisam.", "Thick thatch grass tied in tight bundles along the roof framework.", "छत पर पानी रोकने के लिए कतारों में बाँधी गई सूखी छप्पर की घास।", "Shim-khanao", "Thatch Grass Bundles", "छप्पर की घास"),
